-- ----------------------------------------------------------------------------
-- 4. Tabel Sub Menu: Lembaga Sertifikasi Sistem Manajemen (sertifikat_sistem_manajemen)
-- ----------------------------------------------------------------------------
DROP TABLE IF EXISTS `sertifikat_sistem_manajemen`;
CREATE TABLE `sertifikat_sistem_manajemen` (
